PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL,
  email TEXT,
  display_name TEXT,
  stripe_customer_id TEXT,
  plan TEXT NOT NULL DEFAULT 'free',
  created_at INTEGER NOT NULL
, custom_display_name TEXT, tiktok_profile_id TEXT);
CREATE TABLE frames (
  id TEXT PRIMARY KEY,
  owner_id TEXT,
  image_key TEXT NOT NULL,
  title TEXT,
  created_at INTEGER NOT NULL, custom_name TEXT, expires_at INTEGER, password_hash TEXT, password_ciphertext TEXT, opening_mask_key TEXT, view_count INTEGER NOT NULL DEFAULT 0, wear_count INTEGER NOT NULL DEFAULT 0, good_count INTEGER NOT NULL DEFAULT 0, exclude_from_rankings INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (owner_id) REFERENCES users(id)
);
CREATE TABLE share_urls (
  id TEXT PRIMARY KEY,
  frame_id TEXT NOT NULL,
  access_count INTEGER NOT NULL DEFAULT 0,
  max_access INTEGER,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (frame_id) REFERENCES frames(id)
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE frame_goods (
  frame_id TEXT NOT NULL,
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  UNIQUE(frame_id, actor_type, actor_id),
  FOREIGN KEY (frame_id) REFERENCES frames(id)
);
CREATE TABLE anonymous_user_numbers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL UNIQUE
);
CREATE TABLE frame_views (
  frame_id TEXT NOT NULL,
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  UNIQUE(frame_id, actor_type, actor_id),
  FOREIGN KEY (frame_id) REFERENCES frames(id)
);
CREATE TABLE frame_view_events (
  id TEXT PRIMARY KEY,
  frame_id TEXT NOT NULL,
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (frame_id) REFERENCES frames(id)
);
CREATE TABLE frame_wear_events (
  id TEXT PRIMARY KEY,
  frame_id TEXT NOT NULL,
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (frame_id) REFERENCES frames(id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_frame_goods_frame_id ON frame_goods(frame_id);
CREATE INDEX idx_frame_goods_actor ON frame_goods(actor_type, actor_id);
CREATE INDEX idx_frame_views_frame_id ON frame_views(frame_id);
CREATE INDEX idx_frame_views_actor ON frame_views(actor_type, actor_id);
CREATE INDEX idx_frame_view_events_frame_created_at ON frame_view_events(frame_id, created_at);
CREATE INDEX idx_frame_view_events_created_at ON frame_view_events(created_at);
CREATE INDEX idx_frame_view_events_actor_created_at ON frame_view_events(actor_type, actor_id, created_at);
CREATE INDEX idx_frame_wear_events_frame_created_at ON frame_wear_events(frame_id, created_at);
CREATE INDEX idx_frame_wear_events_created_at ON frame_wear_events(created_at);
CREATE INDEX idx_frame_wear_events_actor_created_at ON frame_wear_events(actor_type, actor_id, created_at);
CREATE INDEX idx_frames_exclude_from_rankings
  ON frames(exclude_from_rankings);
